pub fn ones_like<T>(a: &Vec<T>) -> Vec<i32> {
    let len = a.len();
    let mut result: Vec<i32> = Vec::with_capacity(len);

    // Loop from 0 up to len, pushing 1 each time.
    // Conceptual invariants:
    // - 0 <= i <= len
    // - result.len() == i (before push) / i + 1 (after push)
    // - all elements in result are 1
    for _i in 0..len {
        result.push(1);
    }

    result
}

